function buildPrompt(lot, prereq) {
  const prereqText = prereq
    ? `\n\nDELIVERED JUST BEFORE YOU by the prerequisite lots (use them; their own reviewers may still polish them meanwhile, contracts stay stable):\n${JSON.stringify(prereq, null, 2)}`
    : ''
  return `${COMMON}${prereqText}\n\nYOUR STACK / PORTS / DATABASES: ${lot.stack}.\n\n${lot.prompt}`
}

function reviewPrompt(lot, built, extra) {
  return `${COMMON}\n\nYOUR STACK / PORTS / DATABASES: ${lot.stack} (same as the builder of this lot, who has finished).${extra ?? ''}\n\nYOU ARE THE INDEPENDENT REVIEWER of lot "${lot.key}". The builder's brief was:\n<<<BRIEF\n${lot.prompt}\nBRIEF>>>\n\nThe builder reported:\n${JSON.stringify(built ?? { note: 'builder returned nothing — inspect the files yourself' }, null, 2)}\n\nReview ONLY this lot's owned paths, skeptically, and FIX what is wrong directly in those paths (same ownership rules). In this order: (1) every PROVIDED contract exists with the exact names/signatures of the brief, and consumed contracts are used correctly (read the other lots' real files); (2) honesty: no hardcoded business data, no fake connected/success state, NO DEAD BUTTON — click every control of every page/state and follow it to its real effect; (3) Figma fidelity: bring the lot's stack up, seed it, take screenshots at 1440×1000 and 390×844 of every page and state of the lot and compare them side by side with the listed exports; fix deviations in spacing, sizes, colours, typography, radii, states and verbatim copy (straight apostrophe); (4) security: requireUser/apiRoute everywhere, Origin checks on mutations, Zod at every boundary, no secret reaching the browser or logs, audit of sensitive actions, rate limits, path/branch validation, Claude compliance; (5) resilience: runner down, empty data, upstream errors, double submit, refresh, back/forward, phone layout, slow network, stream.reset; (6) tests: run the lot's unit tests and e2e specs on desktop AND mobile, add the missing critical ones. Do not rewrite working code for taste. Finish with tsc / oxlint / tests green for this lot's files, then bring your stack down and free your ports. List in files_changed every file you modified.`
}

phase('Prérequis')
log('Prérequis : stack de test locale et terminal partagé (en parallèle)')
const prereqBuilt = await parallel(
  PREREQ.map((lot) => () => agent(buildPrompt(lot), { label: `build:${lot.key}`, phase: 'Prérequis', schema: RESULT_SCHEMA })),
)
const prereqSummary = PREREQ.map((lot, i) => ({
  lot: lot.key,
  contracts_provided: prereqBuilt[i]?.contracts_provided ?? ['(lot returned nothing — read its files: ' + lot.key + ')'],
  delivered: prereqBuilt[i]?.delivered ?? [],
  known_gaps: prereqBuilt[i]?.known_gaps ?? [],
}))
log('Prérequis livrés : lancement des 6 domaines et des revues des prérequis')

const prereqReviewsPromise = parallel(
  PREREQ.map((lot, i) => () =>
    agent(
      reviewPrompt(
        lot,
        prereqBuilt[i],
        '\nIMPORTANT: six domain lots are USING these files right now with their own stacks. Keep every command, flag, export and route backward compatible; make small careful edits and re-test immediately; never leave a file broken between two edits; never touch the domain lots\' stacks (other names/ports).',
      ),
      { label: `review:${lot.key}`, phase: 'Revue', schema: REVIEW_SCHEMA },
    ),
  ),
)

const domainsPromise = pipeline(
  DOMAINS,
  (lot) => agent(buildPrompt(lot, prereqSummary), { label: `build:${lot.key}`, phase: 'Domaines', schema: RESULT_SCHEMA }),
  (built, lot) =>
    agent(reviewPrompt(lot, built), { label: `review:${lot.key}`, phase: 'Revue', schema: REVIEW_SCHEMA }).then((review) => ({
      key: lot.key,
      built,
      review,
    })),
)

const [prereqReviews, domains] = await Promise.all([prereqReviewsPromise, domainsPromise])

return {
  prereq: PREREQ.map((lot, i) => ({ key: lot.key, built: prereqBuilt[i], review: prereqReviews[i] })),
  domains: domains.filter(Boolean),
}
